 public function test_private_tax_source_requires_explicit_private_serialization():void {$source=\CetechDeliveryEngine\Application\DeliveryQuote\QuoteNativeTaxSource::from_native_state(QuoteNativeState::from_array(self::facts()));foreach([static fn()=>json_encode($source,JSON_THROW_ON_ERROR),static fn()=>serialize($source)] as $export){try{$export();self::fail('Taxsource was disclosed.');}catch(\LogicException){self::assertTrue(true);}}}
 public function test_wrong_owner_or_site_refuses_before_current_private_reads():void {
  $receipt=(new QuoteNativeReceiptCapture(self::source()))->capture(QuoteFixtures::owner(),self::requests());$context=$receipt->bind_context(QuoteFixtures::context());$session=$this->native_session();$session->expects(self::never())->method('get_results');$facts=QuoteFixtures::owner()->facts();$facts['principal_hash']=QuoteFixtures::digest('foreign');self::assertFalse($receipt->guard()->verify($session,QuoteOwner::from_array($facts),$context));
  $foreign=$this->createMock(\CetechDeliveryEngine\Domain\Operation\OperationSession::class);$foreign->method('site_id')->willReturn(2);$foreign->expects(self::never())->method('get_results');self::assertFalse($receipt->guard()->verify($foreign,QuoteFixtures::owner(),$context));
 }
 private function native_session():\CetechDeliveryEngine\Domain\Operation\OperationSession {
  $session=$this->createMock(\CetechDeliveryEngine\Domain\Operation\OperationSession::class);$session->method('site_id')->willReturn(1);$session->method('table_prefix')->willReturn('wp_');$session->method('prepare')->willReturnCallback(static function(string $sql,mixed ...$args):string{$value=$args[0];if(is_array($value)){$value=$value[0];}return "'".str_replace("'","''",(string)$value)."'";});$session->expects(self::never())->method('query');return $session;
 }

 public function test_state_detaches_reference_mutations():void{$facts=self::facts();$label='Delivery';$facts['packages'][0]['label']=&$label;$state=QuoteNativeState::from_array($facts);$label='PRIVATE';self::assertSame('Delivery',$state->facts()['packages'][0]['label']);}
}
/** Synthetic native attestation only. It does not qualify actual Woo money. */
final class NativeReceiptFixtureSource implements QuoteNativeCaptureSource {
 public int $reads=0;public bool $same=true;public bool $revoke_after_read=false;
 public function __construct(private array $facts){}
 public function current_owner():QuoteOwner{$facts=QuoteFixtures::owner()->facts();if($this->revoke_after_read&&$this->reads>0){$facts['principal_hash']=QuoteFixtures::digest('revoked');}return QuoteOwner::from_array($facts);}
 public function capture():QuoteNativeState{++$this->reads;return QuoteNativeState::from_array($this->facts);}
 public function unchanged():bool{return $this->same;}
}
